import re

input_file = r'C:\Users\renu5\Downloads\college\College sem 5\ecm\ECM_COMPLETE_StudyGuide.md'
output_file = r'C:\Users\renu5\Downloads\college\College sem 5\ecm\ECM_QA_Only.md'

with open(input_file, 'r', encoding='utf-8') as f:
    lines = f.readlines()

qas = []
current_qa = None

for line in lines:
    stripped_line = line.strip()
    if stripped_line.startswith('**Q:') or stripped_line.startswith('**Question:**'):
        if current_qa is not None:
            qas.append(current_qa)
        clean_q = stripped_line.replace('**', '')
        bold_q = f'**{clean_q}**'
        current_qa = {'question': bold_q, 'answer': []}
    elif current_qa is not None:
        if stripped_line.startswith('#') or stripped_line == '---':
            continue
        # Also let's ignore 'The following questions need hand-drawn diagrams...'
        if stripped_line.startswith('The following questions need'):
            continue
        current_qa['answer'].append(line.rstrip())

if current_qa is not None:
    qas.append(current_qa)

with open(output_file, 'w', encoding='utf-8') as f:
    for qa in qas:
        f.write(qa['question'] + '\n\n')
        answer_text = '\n'.join(qa['answer']).strip()
        if answer_text:
            f.write(answer_text + '\n\n')
        else:
            f.write('\n')

print(f'Extracted {len(qas)} questions with answers to {output_file}')
"

